import subprocess
import json

try:
    process = subprocess.run(
        ["/opt/runners/task-runner-python/.venv/bin/python", "/home/runner/Telegram-new-Message.py"],
        capture_output=True, text=True
    )

    # If the script failed (exit code not 0)
    if process.returncode != 0:
        return [{"json": {
            "status": "script_failed",
            "exit_code": process.returncode,
            "error_traceback": process.stderr.strip() 
        }}]

    script_output = json.loads(process.stdout)
    return [{"json": script_output}]

except Exception as e:
    return [{"json": {"error": str(e)}}]
